    /// representative.
    fn unnamed_location_offset(vn: &Varnode) -> u64 {
        if let Some(high_arc) = vn.high.as_ref() {
            if let Some(rep_arc) = high_arc.read().unwrap().get_name_representative() {
                return rep_arc.read().unwrap().get_offset();
            }
        }
        vn.get_offset()
    }

