    ///   if (checkAddressOfCast(op)) {        // &arr decayed to ptr
    ///     pushOp(&addressof,op);
    ///     pushVn(op->getIn(0),op,mods);
    ///     return;
    ///   }
    /// }
    /// if (!option_nocasts) {
    ///   pushOp(&typecast,op);
    ///   pushType(dt);
    /// }
    /// pushVn(op->getIn(0),op,mods);
    /// ```
